'''def max_fill(grid, capacity):
    n = len(grid)
    m = len(grid[0])
    res = 0
    for i in range(n):
        j = 0
        water = 0
        while j < m and water < capacity:
            if grid[i][j] == 1:
                water += 1
            j += 1
        res += water // capacity
        for j in range(m):
            if grid[i][j] == 1:
                grid[i][j] = 0
    return res'''

